        case 0x16: ADSTUB("A88F_OSDisp_sel16_zero"); r.a[7]+=2;  mem->write_u32b(r.a[7], 0); break;
        case 0x18: ADSTUB("A88F_OSDisp_sel18_const"); r.a[7]+=2;  mem->write_u32b(r.a[7], 0x02000000); break;
