            uint32_t stp = mem->read_u32b(r.a[7]+2);   // &status (pointer arg)
            r.a[7]+=10;                                 // pop selector + 2 long args (no result slot)
            if(stp>0x1000) mem->write_u16b(stp, 0);     // noErr
