              if(m>=4) bit^=1;                                  // notSrc* modes invert the mask first
              switch(m&3){
                case 0: px = bit ? C.qd_fg : C.qd_bg; break;    // srcCopy/notSrcCopy: opaque, both bits
                case 1: if(!bit) continue; px=C.qd_fg; break;   // srcOr/notSrcOr: 1 -> fg, 0 transparent
                case 3: if(!bit) continue; px=C.qd_bg; break;   // srcBic/notSrcBic: 1 -> bg, 0 transparent
                default: px = bit ? C.qd_fg : C.qd_bg; break;   // srcXor/notSrcXor: no indexed-XOR
                                                                // semantics here; fall back to copy
              }
