      auto rdrect=[&](uint32_t p,int&t,int&l,int&b,int&rr){ t=(int16_t)mem->read_u16b(p);
        l=(int16_t)mem->read_u16b(p+2); b=(int16_t)mem->read_u16b(p+4); rr=(int16_t)mem->read_u16b(p+6); };
