        mem->write_u16b(port+0x08,(uint16_t)t); mem->write_u16b(port+0x0A,(uint16_t)l);
        mem->write_u16b(port+0x0C,(uint16_t)b); mem->write_u16b(port+0x0E,(uint16_t)rr);   // portRect
        mem->write_u32b(port+0x18, C.g_visrgn);
