        uint32_t ret=0,a0=0,a1=0,a2=0; try{ret=mem->read_u32b(rr.a[7]);}catch(...){}
        try{a0=mem->read_u32b(rr.a[7]+4);}catch(...){} try{a1=mem->read_u32b(rr.a[7]+8);}catch(...){}
        try{a2=mem->read_u32b(rr.a[7]+12);}catch(...){}
